import{_ as o,l as i,o as e,c as l,v as t,p as s,x as r,d,i as E,S as m}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"嵌套交叉验证","description":"","frontmatter":{"title":"嵌套交叉验证","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/nested-cv.md","filePath":"quant/nested-cv.md","lastUpdated":1789023840000}'),h={name:"quant/nested-cv.md"};function c(B,a,p,A,u,f){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="嵌套交叉验证" tabindex="-1">嵌套交叉验证 <a class="header-anchor" href="#嵌套交叉验证" aria-label="Permalink to &quot;嵌套交叉验证&quot;">​</a></h1><div class="epigraph"><p>用同一折既选超参数又报告误差，折外分数是有偏的乐观；必须把选择关在内层，把评估留给从未参与选择的外层。</p><footer>—— 据 Varma and Simon, Bias in Error Estimation When Using Cross-Validation for Model Selection, BMC Bioinformatics, 2006；Cawley and Talbot, On Over-fitting in Model Selection and Subsequent Selection Bias in Performance Evaluation, JMLR, 2010</footer></div><p>交叉验证本意是估计泛化误差。一旦折外分数被用来在模型、正则、窗口、特征子集之间做选择，它就不再是误差的无偏估计——选择把噪声抬进了「最好」的那个配置，报告的数字是最大值的期望，不是任一配置的期望。Varma 与 Simon、Cawley 与 Talbot 把这层偏差写成嵌套交叉验证（nested cross-validation）要消灭的对象：内层循环只负责选择，外层循环只负责评估，外层测试折从不进入网格。金融里同一逻辑更硬，因为标签重叠、非平稳与 <a href="/quant/walk-forward">滚动检验</a> 上的第二次选择几乎是默认操作。本篇写嵌套结构、与 <a href="/quant/pbo">PBO</a> / <a href="/quant/cpcv">CPCV</a> 的分工，以及非嵌套 \\(K\\) 折为什么会系统性夸大截面预测力。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设算法有超参数 \\(\\lambda\\)（树深、惩罚系数、回看窗口、是否加某过滤器）。非嵌套做法是：在全部数据上做一次 \\(K\\) 折，每个 \\(\\lambda\\) 得到一个折外分数，挑 \\(\\lambda^\\star\\)，再把 \\(\\lambda^\\star\\) 的折外分数当作泛化误差去写研报。错误在于 \\(\\lambda^\\star\\) 的折外分数参与了比较。即使所有 \\(\\lambda\\) 真误差相同，最大值的期望仍高于真误差。Cawley–Talbot 强调：模型选择的过拟合与模型拟合的过拟合是两件事；只对后者做正则、却用同一验证集做前者，偏差不会消失。</p><p>金融版本往往更隐蔽。研究者用 2010–2018 做滚动选参，用 2019–2021 看结果，觉得这已经是样本外；若 2019–2021 被用来在五种信号、三种成本假设、两次窗口长度之间再挑一次，外层仍然泄漏。Walk-forward 效率、样本外夏普、折外 \\(R^2\\)，只要还用于选择，就回到非嵌套。问题是给出一个协议，使「选 \\(\\lambda\\)」与「估误差」使用不相交的信息。</p><h3 id="内层与外层的信息集" tabindex="-1">内层与外层的信息集 <a class="header-anchor" href="#内层与外层的信息集" aria-label="Permalink to &quot;内层与外层的信息集&quot;">​</a></h3><p>嵌套结构有两层划分。外层把样本切成 \\(K_{\\mathrm{out}}\\) 个评估折（金融里应是时间块或滚动窗口，禁止打乱）。对每一个外层训练部分，再做一次内层交叉验证或内层滚动，只在这部分上搜索 \\(\\lambda\\)，得到 \\(\\lambda^\\star_{\\mathrm{inner}}\\)，然后在对应的外层测试折上评估<strong>一次</strong>。最终报告的是 \\(K_{\\mathrm{out}}\\) 个外层分数的分布或拼接曲线，不是内层最好折的数字。\\(\\lambda\\) 可以在各外层训练段上不同，这正是非平稳下应该发生的事；把它们平均成一个「最终超参」只是为了部署方便，评估仍以外层为准。</p><p><span class="marginnote">sklearn 式 <code>GridSearchCV</code> 之后再在全样本上报 <code>best_score_</code>，就是非嵌套。金融库若把「验证段夏普」既用于早停又用于选模型再写进表格，同样有偏。早停是内层的事，表格只能写外层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>嵌套滚动。</strong> 外层：用 \\([t-W_{\\mathrm{out}},t)\\) 之前的全部历史当外层训练，用 \\([t,t+H)\\) 当外层测试，向前推进。内层：仅在外层训练段里再切验证窗，搜索网格（深度、学习率、回看、\\(L_1\\) 惩罚、是否行业中性），按内层验证的扣费后目标选出 \\(\\lambda^\\star\\)，冻结核到外层测试段。外层测试段禁止再调仓规则、再改成本、再剔品种。这与机器学习教材里的 nested CV 同构，只是划分必须遵守时间箭头，并在接缝处对重叠标签做 purge，见 <a href="/quant/cv-leakage-finance">泄漏</a>。</p><p><strong>嵌套 CPCV。</strong> 若目的是估计选择偏差而不是给出一条可部署曲线，外层可以用组合划分生成许多条评估路径，内层在每条路径的训练块上做网格。计算更重，但对「网格这一层」的过拟合更敏感。与只对冻结候选算 <a href="/quant/pbo">PBO</a> 的差别是：这里网格尚未冻结，内层就是在生成候选；PBO 假设候选列表已闭合。</p><p><strong>特征选择也要进内层。</strong> 先在全样本上按 IC 或 MDA 筛列，再对外层做交叉验证，等于把特征选择的尝试次数藏起来。筛列、标准化、PCA、行业收益估计，必须 <code>fit</code> 在当前内层训练折上。这与 <a href="/quant/point-in-time">点-in-time</a> 是同一纪律在验证协议上的投影。</p><h3 id="偏差—方差与计算预算" tabindex="-1">偏差—方差与计算预算 <a class="header-anchor" href="#偏差—方差与计算预算" aria-label="Permalink to &quot;偏差—方差与计算预算&quot;">​</a></h3><p>嵌套把用于评估的样本「用得更干净」，但每层都会减小训练长度。外层折太少，外层分数方差大，你得到无偏却无用的区间；内层折太少，选择本身不稳定，\\(\\lambda^\\star\\) 乱跳。Cawley–Talbot 指出选择偏差可以很大，即使样本量看起来不少。金融信噪比低，网格应先靠经济约束削薄（换手上限、可交易宇宙、禁止用未来函数），而不是靠把网格加密再靠嵌套去「修正」。嵌套不是对任意宽搜索的许可证。</p><p>计算上，外层 \\(K_{\\mathrm{out}}\\) 乘内层 \\(K_{\\mathrm{in}}\\) 乘网格大小。应对配置向量化评分；订单级回测放在外层最终候选上，而不是对每个内层格子重放逐笔。若评分函数本身有泄漏（全样本 rank 断点），嵌套只是把泄漏嵌套地复制。</p><p><span class="marginnote">外层分数的均值仍可能因为非平稳而不可外推到下一体制。无偏是相对「同一数据生成过程上的选择过程」而言的，不是相对未来市场。嵌套之后仍要保留一段从未碰过的持有期样本，或接受「没有这样的样本」这一事实。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>非嵌套的乐观偏差来自对验证分数取最大值。验证分数是真误差加噪声，噪声在选择中被系统性地挑中。嵌套把最大值留在内层，外层看到的是「这个选择程序在新块上的实现」，期望对应选择程序的风险，而不是对应被选中配置在验证集上的噪声。Varma–Simon 在小样本分类上显示非嵌套 CV 可以显著低估误差；金融标签的信噪比更低，同一机制只会被放大。</p><p>与多重检验的关系：网格点就是尝试次数。嵌套并不减少尝试，它只是不让你用尝试所依据的那些分数去报成绩。尝试次数仍应进入 <a href="/quant/deflated-sharpe">DSR</a> 的 \\(N\\)，或进入 <a href="/quant/white-reality-check">White Reality Check</a> 的规则集合。嵌套是评估协议，不是把 \\(N\\) 变回 1 的魔法。</p><h3 id="何时不必嵌套" tabindex="-1">何时不必嵌套 <a class="header-anchor" href="#何时不必嵌套" aria-label="Permalink to &quot;何时不必嵌套&quot;">​</a></h3><p>若超参数在样本开始之前就冻结（预注册、沿用上一产品的参数、只用经济常数），没有选择，单层因果滚动就够。若网格极粗且所有格子外层表现几乎一样，选择偏差小，嵌套与否差几个基点——但仍应报告「未选择」。危险的是中等宽度的网格：看起来很克制，恰好足够吸收一段历史的噪声。经验上，凡是「我们试了几种窗口，取了验证最好的」都需要嵌套或把尝试计入 \\(N\\)。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>嵌套不修复前视特征、不修复用未来成交量做的 VWAP 假设、不修复全样本行业分类修订。它只修复「用评估数据选模型」这一层。外层若仍是随机 \\(K\\) 折而不是时间块，泄漏协议比嵌套更优先。也不要把外层 \\(K_{\\mathrm{out}}\\) 条路径的最大值写成「样本外夏普」——那又是一次选择，见 <a href="/quant/overfit-as-risk">过拟合作为风险</a>。</p><p>部署时需要一个单一 \\(\\lambda\\)。常见做法是在全部训练历史（不含最终持有期）上重跑一次内层选择，得到部署参数，评估数字仍然只用外层历史路径。不要用外层测试去微调后再报同一段外层。内层目标必须与外层评估对齐：内层用毛 \\(R^2\\)、外层用扣费夏普，选择会偏向高换手；两边都应是扣费后、容量约束后的同一效用。</p><p><span class="marginnote">嵌套交叉验证的计算成本常被拿来当不做的理由。更便宜的替代是大幅缩小网格并预注册，而不是回到非嵌套的 <code>best_score_</code>。宽搜索加非嵌套，是最贵的那种便宜。</span></p>',26)),(e(),s(m,null,{default:r(()=>[E(n,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20TD%0A%20%20DATA%5B%22%E6%97%B6%E9%97%B4%E6%9C%89%E5%BA%8F%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20OUT%5B%22%E5%A4%96%E5%B1%82%E5%88%92%E5%88%86%EF%BC%9A%E8%AE%AD%E7%BB%83%20%2F%20%E6%B5%8B%E8%AF%95%22%5D%0A%20%20OUT%20--%3E%20IN%5B%22%E4%BB%85%E5%9C%A8%E5%A4%96%E5%B1%82%E8%AE%AD%E7%BB%83%E4%B8%8A%EF%BC%9A%E5%86%85%E5%B1%82%20CV%20%E6%88%96%E6%BB%9A%E5%8A%A8%22%5D%0A%20%20IN%20--%3E%20GRID%5B%22%E6%90%9C%E7%B4%A2%20%CE%BB%E3%80%81%E7%89%B9%E5%BE%81%E5%AD%90%E9%9B%86%E3%80%81%E7%AA%97%E5%8F%A3%22%5D%0A%20%20GRID%20--%3E%20LAM%5B%22%E5%BE%97%E5%88%B0%20%CE%BB*%22%5D%0A%20%20LAM%20--%3E%20EVAL%5B%22%E5%8F%AA%E5%9C%A8%E5%A4%96%E5%B1%82%E6%B5%8B%E8%AF%95%E8%AF%84%E4%BC%B0%E4%B8%80%E6%AC%A1%22%5D%0A%20%20EVAL%20--%3E%20DIST%5B%22%E5%A4%96%E5%B1%82%E5%88%86%E6%95%B0%E5%88%86%E5%B8%83%20%2F%20%E6%8B%BC%E6%8E%A5%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20DIST%20--%3E%20REP%5B%22%E6%8A%A5%E5%91%8A%E5%88%86%E5%B8%83%EF%BC%8C%E7%A6%81%E6%AD%A2%E5%86%8D%E9%80%89%E6%9C%80%E5%A4%A7%E5%80%BC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>非嵌套交叉验证用同一折既选模型又报误差，折外分数是最大值的有偏估计。</li><li>嵌套把选择关在内层，外层测试折不参与网格、早停与特征筛列。</li><li>金融里外层应是时间块或滚动，接缝处清洗标签；特征管道的 <code>fit</code> 必须停在内层训练折。</li><li>嵌套不把尝试次数变回 1，DSR / Reality Check / PBO 仍要计 \\(N\\)。</li><li>预注册的窄网格可以不嵌套；凡是「试了几种取最好」就必须嵌套或把尝试写入评估。</li><li>出处：Varma and Simon, <em>BMC Bioinformatics</em>, 2006；Cawley and Talbot, <em>JMLR</em>, 2010；López de Prado, <em>Advances in Financial Machine Learning</em>, 2018；Arnott, Harvey and Markowitz, <em>Journal of Portfolio Management</em>, 2019。</li></ul>',2))])}const b=o(h,[["render",c]]);export{_ as __pageData,b as default};
